1	package oci
2	
3	import (
4		"context"
5		"crypto/sha256"
6		"encoding/hex"
7		"errors"
8		"fmt"
9		"hash"
10		"io"
11		"net"
12		"net/http"
13		"net/netip"
14		"net/url"
15		"strconv"
16		"strings"
17		"sync"
18		"syscall"
19		"time"
20	)
21	
22	// This file holds what the layer blob download needs on top of Client: the
23	// redirect policy, the SSRF guard on the dialed address, the proxy allowance,
24	// the error rewriting and the byte cap. See DEVDESK-412.
25	
26	// errBlobRedirectLocal is the refusal of a blob redirect to a loopback or
27	// link-local address from a registry that is not itself local, so a registry
28	// cannot make DevDesk query a service on this machine or the cloud metadata
29	// endpoint (SSRF). It names no URL: the target may be signed.
30	var errBlobRedirectLocal = errors.New("refusing redirect to a loopback or link-local address")
31	
32	// errBlobDialLocal is the refusal of dialControl to connect to such an address,
33	// whatever name led there (DNS rebinding included).
34	var errBlobDialLocal = errors.New("refusing to connect to a loopback or link-local address")
35	
36	// isLocalHost reports whether host (no port) is local: localhost, any name under
37	// .localhost (compared without case, with or without the final dot), or a literal
38	// loopback, link-local or unspecified address, IPv4-mapped forms included. The
39	// unspecified address counts because Linux connects it to this machine. Any
40	// other name is not local here, whatever /etc/hosts or the DNS say: only the
41	// dial control sees what it resolves to.
42	func isLocalHost(host string) bool {
43		name := strings.ToLower(strings.TrimSuffix(host, "."))
44		if name == "localhost" || strings.HasSuffix(name, ".localhost") {
45			return true
46		}
47		addr, err := netip.ParseAddr(host)
48		return err == nil && isLocalAddr(addr)
49	}
50	
51	func isLocalAddr(addr netip.Addr) bool {
52		addr = addr.Unmap().WithZone("")
53		return addr.IsLoopback() || addr.IsLinkLocalUnicast() || addr.IsUnspecified()
54	}
55	
56	// isLocalURL reports whether the host of rawURL is local (see isLocalHost). A URL
57	// that does not parse is not local.
58	func isLocalURL(rawURL string) bool {
59		u, err := url.Parse(rawURL)
60		return err == nil && isLocalHost(u.Hostname())
61	}
62	
63	// blobDialControl is a net.Dialer Control that refuses to connect to a loopback
64	// or link-local address unless allowLocal. It runs on the address about to be
65	// dialed, so a name that resolves to such an address (DNS rebinding) is caught
66	// where followBlobRedirect, which only sees names, cannot. An address that
67	// cannot be read is refused.
68	func blobDialControl(allowLocal bool) func(network, address string, c syscall.RawConn) error {
69		return dialControl(allowLocal, nil)
70	}
71	
72	// dialControl is blobDialControl that also lets through the address of a proxy
73	// the transport was told to use (see proxyAddrs): a local proxy such as
74	// cntlm on 127.0.0.1 is the user's own configuration, not a redirect target.
75	func dialControl(allowLocal bool, proxies *proxyAddrs) func(network, address string, c syscall.RawConn) error {
76		return func(_, address string, _ syscall.RawConn) error {
77			if allowLocal {
78				return nil
79			}
80			ap, err := netip.ParseAddrPort(address)
81			if err != nil {
82				return errBlobDialLocal
83			}
84			ap = netip.AddrPortFrom(ap.Addr().Unmap().WithZone(""), ap.Port())
85			if isLocalAddr(ap.Addr()) && !proxies.has(ap) {
86				return errBlobDialLocal
87			}
88			return nil
89		}
90	}
91	
92	// proxyAddrs holds the ip:port of the proxies the blob transport was asked to
93	// use, filled by the transport's Proxy function just before it dials. A proxy
94	// that NO_PROXY excludes for a request is therefore never allowed on its
95	// account. The target of a proxied request is resolved by the proxy, so the
96	// literal check of followBlobRedirect stays the guard for it.
97	type proxyAddrs struct {
98		resolveMu sync.Mutex // serializes lookups
99		resolve   func(host string) ([]netip.Addr, error)
100	
101		mu    sync.Mutex // guards seen and addrs
102		seen  map[string]bool
103		addrs map[netip.AddrPort]bool
104	}
105	
106	func newProxyAddrs() *proxyAddrs {
107		return &proxyAddrs{resolve: resolveProxyHost, seen: map[string]bool{}, addrs: map[netip.AddrPort]bool{}}
108	}
109	
110	func (p *proxyAddrs) has(ap netip.AddrPort) bool {
111		if p == nil {
112			return false
113		}
114		p.mu.Lock()
115		defer p.mu.Unlock()
116		return p.addrs[ap]
117	}
118	
119	// add records the addresses proxy resolves to, looking each proxy up until it
120	// resolves once. A proxy that does not resolve adds nothing, so a local address
121	// stays refused.
122	func (p *proxyAddrs) add(proxy *url.URL) {
123		port := proxyPort(proxy)
124		key := net.JoinHostPort(proxy.Hostname(), strconv.Itoa(int(port)))
125		// One lookup at a time, with the result recorded before the next request
126		// looks: a concurrent request waits instead of seeing a proxy that is marked
127		// known but has no address yet. has takes mu only, so a dial never waits for
128		// a lookup.
129		p.resolveMu.Lock()
130		defer p.resolveMu.Unlock()
131		p.mu.Lock()
132		done := p.seen[key]
133		p.mu.Unlock()
134		if done {
135			return
136		}
137		resolved, err := p.resolve(proxy.Hostname())
138		if err != nil {
139			return // not remembered: the next request looks again
140		}
141		p.mu.Lock()
142		defer p.mu.Unlock()
143		for _, addr := range resolved {
144			p.addrs[netip.AddrPortFrom(addr.Unmap().WithZone(""), port)] = true
145		}
146		p.seen[key] = true
147	}
148	
149	// proxyPort is the port net/http dials for proxy: the one in its URL, else the
150	// default of its scheme.
151	func proxyPort(proxy *url.URL) uint16 {
152		if n, err := strconv.ParseUint(proxy.Port(), 10, 16); err == nil {
153			return uint16(n)
154		}
155		switch proxy.Scheme {
156		case "https":
157			return 443
158		case "socks5", "socks5h":
159			return 1080
160		}
161		return 80
162	}
163	
164	// resolveProxyHost gives the addresses a proxy host stands for: a literal
165	// address as is, localhost and the names under it as the two loopback addresses,
166	// any other name through the resolver, bounded to 5 seconds.
167	func resolveProxyHost(host string) ([]netip.Addr, error) {
168		if addr, err := netip.ParseAddr(host); err == nil {
169			return []netip.Addr{addr}, nil
170		}
171		if isLocalHost(host) { // a name under .localhost (an address was handled above)
172			return []netip.Addr{netip.MustParseAddr("127.0.0.1"), netip.MustParseAddr("::1")}, nil
173		}
174		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
175		defer cancel()
176		return net.DefaultResolver.LookupNetIP(ctx, "ip", host)
177	}
178	
179	// blobTransport is http.DefaultTransport (proxy settings included) with
180	// blobDialControl on its dialer.
181	func blobTransport(allowLocal bool) *http.Transport {
182		return newBlobTransport(allowLocal, http.ProxyFromEnvironment)
183	}
184	
185	// newBlobTransport is blobTransport with the proxy selection given, which lets a
186	// test choose the proxy: http.ProxyFromEnvironment reads the environment once
187	// per process.
188	func newBlobTransport(allowLocal bool, proxyFor func(*http.Request) (*url.URL, error)) *http.Transport {
189		proxies := newProxyAddrs()
190		tr := http.DefaultTransport.(*http.Transport).Clone()
191		tr.Proxy = func(req *http.Request) (*url.URL, error) {
192			proxy, err := proxyFor(req)
193			if proxy != nil {
194				proxies.add(proxy)
195			}
196			return proxy, err
197		}
198		tr.DialContext = (&net.Dialer{
199			Timeout:   30 * time.Second,
200			KeepAlive: 30 * time.Second,
201			Control:   dialControl(allowLocal, proxies),
202		}).DialContext
203		return tr
204	}
205	
206	// errBlobRedirectScheme is the refusal of a blob redirect to anything but
207	// http or https. It names no URL: the target may be signed.
208	var errBlobRedirectScheme = errors.New("refusing redirect to a scheme other than http or https")
209	
210	// followBlobRedirect is the CheckRedirect of Client.blobClient.
211	//
212	// Deliberate exception to RefuseOffOriginRedirect (DEVDESK-412, user decision
213	// Q1b): a layer blob may be served from another origin, the usual way a registry
214	// hands it to a CDN or an object store. The redirect is followed, but the
215	// credentials never go with it:
216	//   - at most MaxRedirects hops, only to http or https;
217	//   - never from https to http (compared with the previous hop), so a signed URL
218	//     does not leave in clear;
219	//   - when the registry is not local, never to localhost or a literal loopback
220	//     or link-local address (SSRF; blobDialControl covers names that resolve
221	//     there);
222	//   - once the chain left the origin of the first request (scheme, host and
223	//     port), Authorization is deleted from every following request, including
224	//     one that comes back to the origin. net/http copies the header to the same
225	//     host name on another port, across a scheme change and to a subdomain, and
226	//     it copies it before this function runs, so deleting it here is what counts.
227	//     The Referer net/http sets (the previous hop's full, possibly signed, URL)
228	//     goes the same way.
229	func followBlobRedirect(req *http.Request, via []*http.Request) error {
230		if len(via) >= MaxRedirects {
231			return ErrTooManyRedirects
232		}
233		if req.URL.Scheme != "http" && req.URL.Scheme != "https" {
234			return errBlobRedirectScheme
235		}
236		first := via[0].URL
237		if via[len(via)-1].URL.Scheme == "https" && req.URL.Scheme != "https" {
238			return fmt.Errorf("%w (%s)", errInsecureRedirect, req.URL.Host)
239		}
240		if !isLocalHost(first.Hostname()) && isLocalHost(req.URL.Hostname()) {
241			return fmt.Errorf("%w (%s)", errBlobRedirectLocal, req.URL.Host)
242		}
243		left := !sameOrigin(first.String(), req.URL.String())
244		for _, prev := range via[1:] {
245			left = left || !sameOrigin(first.String(), prev.URL.String())
246		}
247		if left {
248			req.Header.Del("Authorization")
249			req.Header.Del("Referer")
250		}
251		return nil
252	}
253	
254	// blobFetchError rewrites a *url.Error of the blob download so that it carries
255	// the host of the failing hop at most: its URL may hold a signed query or a
256	// private path. The cause stays reachable through errors.Is and errors.As.
257	func blobFetchError(err error) error {
258		var ue *url.Error
259		if !errors.As(err, &ue) {
260			return err
261		}
262		if u, perr := url.Parse(ue.URL); perr == nil && u.Host != "" {
263			return fmt.Errorf("download layer from %s: %w", u.Host, ue.Err)
264		}
265		return fmt.Errorf("download layer: %w", ue.Err)
266	}
267	
268	// blobCap bounds the compressed bytes taken off the network for one layer: the
269	// content limit, a tar header and padding per file, and 1 MiB of gzip framing.
270	// The decompressed Limits do not see everything the network carries: PAX and GNU
271	// extension headers and their padding are not file content (the standard library
272	// caps each at 1 MiB), so this is the only bound on those bytes. 0 means no cap (Limits{} or no byte limit).
273	func blobCap(lim Limits) int64 {
274		if lim.Bytes <= 0 {
275			return 0
276		}
277		return lim.Bytes + int64(lim.Files)*2048 + 1<<20
278	}
279	
280	// cappedReader reads from r, accepting at most left bytes: one more byte
281	// available makes it fail with ErrArchiveTooLarge instead of reading it.
282	type cappedReader struct {
283		r    io.Reader
284		left int64
285	}
286	
287	func (c *cappedReader) Read(p []byte) (int, error) {
288		if len(p) == 0 {
289			return 0, nil
290		}
291		if c.left <= 0 {
292			var probe [1]byte
293			n, err := c.r.Read(probe[:])
294			if n > 0 {
295				return 0, ErrArchiveTooLarge
296			}
297			return 0, err
298		}
299		if int64(len(p)) > c.left {
300			p = p[:c.left]
301		}
302		n, err := c.r.Read(p)
303		c.left -= int64(n)
304		return n, err
305	}
306	
307	// ErrBlobDigestMismatch is returned when the layer received is not the one the
308	// manifest names. No entry is returned with it.
309	var ErrBlobDigestMismatch = errors.New("layer content does not match its digest")
310	
311	// errBlobDigestForm is the refusal of a layer digest that is not sha256 and 64
312	// lowercase hex digits. It does not repeat the digest: it is what the registry
313	// wrote and may be long or hold control characters.
314	var errBlobDigestForm = errors.New("unsupported layer digest: only sha256 is supported")
315	
316	// parseLayerDigest returns the hex part of digest when it is "sha256:" followed
317	// by exactly 64 lowercase hex digits, and errBlobDigestForm otherwise. The
318	// digest goes into the blob URL, so nothing else (a path, a query, another
319	// algorithm) is accepted.
320	func parseLayerDigest(digest string) (hexPart string, err error) {
321		hexPart, ok := strings.CutPrefix(digest, "sha256:")
322		if !ok || len(hexPart) != sha256.Size*2 {
323			return "", errBlobDigestForm
324		}
325		for i := 0; i < len(hexPart); i++ {
326			if c := hexPart[i]; (c < '0' || c > '9') && (c < 'a' || c > 'f') {
327				return "", errBlobDigestForm
328			}
329		}
330		return hexPart, nil
331	}
332	
333	// checkBlobDigest drains what the archive reader left unread of body, so the
334	// bytes after the gzip stream are part of the digest too, then compares the
335	// hash of everything received with wantHex. The drain is bounded by the reader
336	// it is given (blobCap, or the client timeout when there is no cap); a blob over
337	// the cap comes back as ErrArchiveTooLarge, not as a mismatch.
338	func checkBlobDigest(body io.Reader, sum hash.Hash, wantHex string) error {
339		if _, err := io.Copy(io.Discard, body); err != nil {
340			return err
341		}
342		if got := hex.EncodeToString(sum.Sum(nil)); got != wantHex {
343			return fmt.Errorf("%w (expected sha256:%.12s...)", ErrBlobDigestMismatch, wantHex)
344		}
345		return nil
346	}
