62	
63	// blobDialControl is a net.Dialer Control that refuses to connect to a loopback
64	// or link-local address unless allowLocal. It runs on the address about to be
65	// dialed, so a name that resolves to such an address (DNS rebinding) is caught
66	// where followBlobRedirect, which only sees names, cannot. An address that
67	// cannot be read is refused.
68	func blobDialControl(allowLocal bool) func(network, address string, c syscall.RawConn) error {
69		return dialControl(allowLocal, nil)
