71	
72	// dialControl is blobDialControl that also lets through the address of a proxy
73	// the transport was told to use (see proxyAddrs): a local proxy such as
74	// cntlm on 127.0.0.1 is the user's own configuration, not a redirect target.
75	func dialControl(allowLocal bool, proxies *proxyAddrs) func(network, address string, c syscall.RawConn) error {
76		return func(_, address string, _ syscall.RawConn) error {
77			if allowLocal {
78				return nil
79			}
80			ap, err := netip.ParseAddrPort(address)
81			if err != nil {
82				return errBlobDialLocal
83			}
84			ap = netip.AddrPortFrom(ap.Addr().Unmap().WithZone(""), ap.Port())
85			if isLocalAddr(ap.Addr()) && !proxies.has(ap) {
86				return errBlobDialLocal
