91	
92	// proxyAddrs holds the ip:port of the proxies the blob transport was asked to
93	// use, filled by the transport's Proxy function just before it dials. A proxy
94	// that NO_PROXY excludes for a request is therefore never allowed on its
95	// account. The target of a proxied request is resolved by the proxy, so the
96	// literal check of followBlobRedirect stays the guard for it.
97	type proxyAddrs struct {
98		resolveMu sync.Mutex // serializes lookups
99		resolve   func(host string) ([]netip.Addr, error)
100	
101		mu    sync.Mutex // guards seen and addrs
102		seen  map[string]bool
103		addrs map[netip.AddrPort]bool
104	}
105	
106	func newProxyAddrs() *proxyAddrs {
107		return &proxyAddrs{resolve: resolveProxyHost, seen: map[string]bool{}, addrs: map[netip.AddrPort]bool{}}
108	}
109	
110	func (p *proxyAddrs) has(ap netip.AddrPort) bool {
111		if p == nil {
112			return false
113		}
114		p.mu.Lock()
115		defer p.mu.Unlock()
116		return p.addrs[ap]
117	}
118	
119	// add records the addresses proxy resolves to, looking each proxy up until it
120	// resolves once. A proxy that does not resolve adds nothing, so a local address
121	// stays refused.
122	func (p *proxyAddrs) add(proxy *url.URL) {
123		port := proxyPort(proxy)
124		key := net.JoinHostPort(proxy.Hostname(), strconv.Itoa(int(port)))
125		// One lookup at a time, with the result recorded before the next request
126		// looks: a concurrent request waits instead of seeing a proxy that is marked
127		// known but has no address yet. has takes mu only, so a dial never waits for
128		// a lookup.
129		p.resolveMu.Lock()
130		defer p.resolveMu.Unlock()
131		p.mu.Lock()
132		done := p.seen[key]
133		p.mu.Unlock()
134		if done {
135			return
136		}
137		resolved, err := p.resolve(proxy.Hostname())
138		if err != nil {
139			return // not remembered: the next request looks again
140		}
141		p.mu.Lock()
142		defer p.mu.Unlock()
143		for _, addr := range resolved {
144			p.addrs[netip.AddrPortFrom(addr.Unmap().WithZone(""), port)] = true
145		}
146		p.seen[key] = true
147	}
148	
149	// proxyPort is the port net/http dials for proxy: the one in its URL, else the
150	// default of its scheme.
151	func proxyPort(proxy *url.URL) uint16 {
152		if n, err := strconv.ParseUint(proxy.Port(), 10, 16); err == nil {
153			return uint16(n)
154		}
155		switch proxy.Scheme {
156		case "https":
157			return 443
158		case "socks5", "socks5h":
159			return 1080
160		}
161		return 80
162	}
163	
164	// resolveProxyHost gives the addresses a proxy host stands for: a literal
165	// address as is, localhost and the names under it as the two loopback addresses,
166	// any other name through the resolver, bounded to 5 seconds.
167	func resolveProxyHost(host string) ([]netip.Addr, error) {
168		if addr, err := netip.ParseAddr(host); err == nil {
169			return []netip.Addr{addr}, nil
170		}
171		if isLocalHost(host) { // a name under .localhost (an address was handled above)
172			return []netip.Addr{netip.MustParseAddr("127.0.0.1"), netip.MustParseAddr("::1")}, nil
173		}
174		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
175		defer cancel()
176		return net.DefaultResolver.LookupNetIP(ctx, "ip", host)
177	}
178	
179	// blobTransport is http.DefaultTransport (proxy settings included) with
180	// blobDialControl on its dialer.
181	func blobTransport(allowLocal bool) *http.Transport {
182		return newBlobTransport(allowLocal, http.ProxyFromEnvironment)
183	}
184	
185	// newBlobTransport is blobTransport with the proxy selection given, which lets a
186	// test choose the proxy: http.ProxyFromEnvironment reads the environment once
