204	}
205	
206	// errBlobRedirectScheme is the refusal of a blob redirect to anything but
207	// http or https. It names no URL: the target may be signed.
208	var errBlobRedirectScheme = errors.New("refusing redirect to a scheme other than http or https")
209	
210	// followBlobRedirect is the CheckRedirect of Client.blobClient.
211	//
212	// Deliberate exception to RefuseOffOriginRedirect (DEVDESK-412, user decision
213	// Q1b): a layer blob may be served from another origin, the usual way a registry
214	// hands it to a CDN or an object store. The redirect is followed, but the
215	// credentials never go with it:
216	//   - at most MaxRedirects hops, only to http or https;
217	//   - never from https to http (compared with the previous hop), so a signed URL
218	//     does not leave in clear;
219	//   - when the registry is not local, never to localhost or a literal loopback
220	//     or link-local address (SSRF; blobDialControl covers names that resolve
221	//     there);
222	//   - once the chain left the origin of the first request (scheme, host and
223	//     port), Authorization is deleted from every following request, including
224	//     one that comes back to the origin. net/http copies the header to the same
225	//     host name on another port, across a scheme change and to a subdomain, and
226	//     it copies it before this function runs, so deleting it here is what counts.
227	//     The Referer net/http sets (the previous hop's full, possibly signed, URL)
228	//     goes the same way.
229	func followBlobRedirect(req *http.Request, via []*http.Request) error {
230		if len(via) >= MaxRedirects {
231			return ErrTooManyRedirects
232		}
233		if req.URL.Scheme != "http" && req.URL.Scheme != "https" {
234			return errBlobRedirectScheme
235		}
236		first := via[0].URL
237		if via[len(via)-1].URL.Scheme == "https" && req.URL.Scheme != "https" {
238			return fmt.Errorf("%w (%s)", errInsecureRedirect, req.URL.Host)
239		}
240		if !isLocalHost(first.Hostname()) && isLocalHost(req.URL.Hostname()) {
241			return fmt.Errorf("%w (%s)", errBlobRedirectLocal, req.URL.Host)
242		}
243		left := !sameOrigin(first.String(), req.URL.String())
244		for _, prev := range via[1:] {
245			left = left || !sameOrigin(first.String(), prev.URL.String())
246		}
247		if left {
248			req.Header.Del("Authorization")
249			req.Header.Del("Referer")
250		}
251		return nil
252	}
253	
254	// blobFetchError rewrites a *url.Error of the blob download so that it carries
255	// the host of the failing hop at most: its URL may hold a signed query or a
256	// private path. The cause stays reachable through errors.Is and errors.As.
257	func blobFetchError(err error) error {
258		var ue *url.Error
259		if !errors.As(err, &ue) {
260			return err
261		}
262		if u, perr := url.Parse(ue.URL); perr == nil && u.Host != "" {
263			return fmt.Errorf("download layer from %s: %w", u.Host, ue.Err)
264		}
265		return fmt.Errorf("download layer: %w", ue.Err)
266	}
267	
268	// blobCap bounds the compressed bytes taken off the network for one layer: the
269	// content limit, a tar header and padding per file, and 1 MiB of gzip framing.
270	// The decompressed Limits do not see everything the network carries: PAX and GNU
271	// extension headers and their padding are not file content (the standard library
272	// caps each at 1 MiB), so this is the only bound on those bytes. 0 means no cap (Limits{} or no byte limit).
273	func blobCap(lim Limits) int64 {
274		if lim.Bytes <= 0 {
275			return 0
276		}
277		return lim.Bytes + int64(lim.Files)*2048 + 1<<20
278	}
279	
280	// cappedReader reads from r, accepting at most left bytes: one more byte
281	// available makes it fail with ErrArchiveTooLarge instead of reading it.
282	type cappedReader struct {
283		r    io.Reader
284		left int64
285	}
286	
287	func (c *cappedReader) Read(p []byte) (int, error) {
288		if len(p) == 0 {
289			return 0, nil
290		}
291		if c.left <= 0 {
292			var probe [1]byte
293			n, err := c.r.Read(probe[:])
294			if n > 0 {
295				return 0, ErrArchiveTooLarge
296			}
297			return 0, err
298		}
299		if int64(len(p)) > c.left {
300			p = p[:c.left]
301		}
302		n, err := c.r.Read(p)
303		c.left -= int64(n)
304		return n, err
305	}
306	
307	// ErrBlobDigestMismatch is returned when the layer received is not the one the
308	// manifest names. No entry is returned with it.
309	var ErrBlobDigestMismatch = errors.New("layer content does not match its digest")
310	
311	// errBlobDigestForm is the refusal of a layer digest that is not sha256 and 64
312	// lowercase hex digits. It does not repeat the digest: it is what the registry
313	// wrote and may be long or hold control characters.
314	var errBlobDigestForm = errors.New("unsupported layer digest: only sha256 is supported")
315	
316	// parseLayerDigest returns the hex part of digest when it is "sha256:" followed
317	// by exactly 64 lowercase hex digits, and errBlobDigestForm otherwise. The
318	// digest goes into the blob URL, so nothing else (a path, a query, another
319	// algorithm) is accepted.
320	func parseLayerDigest(digest string) (hexPart string, err error) {
321		hexPart, ok := strings.CutPrefix(digest, "sha256:")
322		if !ok || len(hexPart) != sha256.Size*2 {
323			return "", errBlobDigestForm
324		}
325		for i := 0; i < len(hexPart); i++ {
326			if c := hexPart[i]; (c < '0' || c > '9') && (c < 'a' || c > 'f') {
327				return "", errBlobDigestForm
328			}
329		}
330		return hexPart, nil
331	}
332	
333	// checkBlobDigest drains what the archive reader left unread of body, so the
334	// bytes after the gzip stream are part of the digest too, then compares the
335	// hash of everything received with wantHex. The drain is bounded by the reader
336	// it is given (blobCap, or the client timeout when there is no cap); a blob over
337	// the cap comes back as ErrArchiveTooLarge, not as a mismatch.
338	func checkBlobDigest(body io.Reader, sum hash.Hash, wantHex string) error {
339		if _, err := io.Copy(io.Discard, body); err != nil {
340			return err
341		}
342		if got := hex.EncodeToString(sum.Sum(nil)); got != wantHex {
343			return fmt.Errorf("%w (expected sha256:%.12s...)", ErrBlobDigestMismatch, wantHex)
344		}
345		return nil
346	}
